def solve_game_v2(n):
    cards = list(range(1, n + 1))
    memo = {}

    def get_result(current_cards, current_diff, is_winnie_turn):
        # We want to avoid negative current_diff in the state to improve memoization
        # But wait, the absolute difference is what matters.
        # However, current_diff itself can be positive or negative.
        # Let's use current_diff
        state = (tuple(sorted(current_cards)), current_diff, is_winnie_turn)
        if state in memo:
            return memo[state]

        if not current_cards:
            return abs(current_diff)

        if is_winnie_turn:
            res = -float('inf')
            for i, c in enumerate(current_cards):
                remaining = current_cards[:i] + current_cards[i+1:]
                res = max(res, get_result(remaining, current_diff + c, False))
                res = max(res, get_result(remaining, current_diff - c, False))
            memo[state] = res
            return res
        else:
            res = float('inf')
            for i, c in enumerate(current_cards):
                remaining = current_cards[:i] + current_cards[i+1:]
                res = min(res, get_result(remaining, current_diff + c, True))
                res = min(res, get_result(remaining, current_diff - c, True))
