def brute_force_n4():
    # All possible moves for n=4
    # G1: (c, a) - 4 * 2 = 8 moves
    # W2: (c, a) - 3 * 2 = 6 moves
    # G3: (c, a) - 2 * 2 = 4 moves
    # W4: (c, a) - 1 * 2 = 2 moves
    # Total moves: 8 * 6 * 4 * 2 = 384

    def solve():
        cards = [1, 2, 3, 4]

        def g1(cards):
            best_g1 = float('inf')
            for c1 in cards:
                for a1 in [1, -1]:
                    rem1 = [x for x in cards if x != c1]
                    res = w2(rem1, a1 * c1)
                    if res < best_g1:
                        best_g1 = res
            return best_g1

        def w2(cards, diff):
            best_w2 = -float('inf')
            for c2 in cards:
                for a2 in [1, -1]:
                    rem2 = [x for x in cards if x != c2]
                    res = g3(rem2, diff + a2 * c2)
                    if res > best_w2:
                        best_w2 = res
            return best_w2

        def g3(cards, diff):
            best_g3 = float('inf')
            for c3 in cards:
                for a3 in [1, -1]:
                    rem3 = [x for x in cards if x != c3]
                    res = w4(rem3, diff + a3 * c3)
                    if res < best_g3:
                        best_g3 = res
            return best_g3

        def w4(cards, diff):
            best_w4 = -float('inf')
            for c4 in cards:
                for a4 in [1, -1]:
                    res = abs(diff + a4 * c4)
                    if res > best_w4:
                        best_w4 = res
            return best_w4

        return g1(cards)

    return solve()

